     1	/**
     2	 * A park after normalization. Every optional field is either a usable value
     3	 * or `null` (arrays are empty instead), so UI code never has to re-check
     4	 * the raw data's shape.
     5	 */
     6	export type Park = {
     7	  /** URL-safe identifier, unique across the dataset. */
     8	  id: string;
     9	  name: string;
    10	  description: string | null;
    11	  /** `null` when the source has no usable coordinates; such parks are listed but not mapped. */
    12	  coordinates: Coordinates | null;
    13	  address: string | null;
    14	  /** Amenity slugs as given in the source (e.g. `"dog-run"`), de-duplicated. */
    15	  amenities: string[];
    16	  /** Free-text opening hours exactly as published (e.g. `"Dawn to dusk"`). */
    17	  hours: string | null;
    18	  /** Absolute http(s) image URLs. They may still fail to load at runtime. */
    19	  images: string[];
    20	  acreage: number | null;
    21	  /** Average rating on a 0–5 scale. */
    22	  rating: number | null;
    23	};
    24	
    25	export type Coordinates = { lat: number; lng: number };
    26	
    27	export type ParkWithCoordinates = Park & { coordinates: Coordinates };
    28	
    29	export function hasCoordinates(park: Park): park is ParkWithCoordinates {
    30	  return park.coordinates !== null;
    31	}
=== src/lib/parks/normalize.ts
     1	import type { Coordinates, Park } from "./types";
     2	
     3	/**
     4	 * Turns untrusted park records (e.g. the contents of `parks.sample.json`)
     5	 * into `Park` objects the UI can rely on.
     6	 *
     7	 * Policy: never invent data. A field that is missing, empty or malformed
     8	 * becomes `null` (or `[]`), and the UI says it isn't listed. A record is only
     9	 * dropped when it can't be shown at all — no usable id or name, or an id that
    10	 * duplicates an earlier record. Every dropped record or discarded value is
    11	 * reported in `warnings` so data problems are visible to maintainers.
    12	 */
    13	export function normalizeParks(input: unknown): {
    14	  parks: Park[];
    15	  warnings: string[];
    16	} {
    17	  const warnings: string[] = [];
    18	
    19	  if (!Array.isArray(input)) {
    20	    return { parks: [], warnings: ["Park data is not an array."] };
    21	  }
    22	
    23	  const seenIds = new Set<string>();
    24	  const parks: Park[] = [];
    25	
    26	  input.forEach((record: unknown, index) => {
    27	    const label = `Park #${index}`;
    28	
    29	    if (!isObject(record)) {
    30	      warnings.push(`${label}: skipped because it is not an object.`);
    31	      return;
    32	    }
    33	
    34	    const id = text(record.id);
    35	    if (id === null || !ID_PATTERN.test(id)) {
    36	      warnings.push(`${label}: skipped because it has no valid id.`);
    37	      return;
    38	    }
    39	    if (seenIds.has(id)) {
    40	      warnings.push(`${label}: skipped because id "${id}" is a duplicate.`);
    41	      return;
    42	    }
    43	
    44	    const name = text(record.name);
    45	    if (name === null) {
    46	      warnings.push(`${label} ("${id}"): skipped because it has no name.`);
    47	      return;
    48	    }
    49	
    50	    seenIds.add(id);
    51	    const warn = (message: string) => warnings.push(`"${id}": ${message}`);
    52	    const location = isObject(record.location) ? record.location : {};
    53	
    54	    parks.push({
    55	      id,
    56	      name,
    57	      description: text(record.description),
    58	      coordinates: coordinates(location.lat, location.lng, warn),
    59	      address: text(location.address),
    60	      amenities: stringList(record.amenities, "amenities", warn),
    61	      hours: text(record.hours),
    62	      images: imageUrls(record.images, warn),
    63	      acreage: numberInRange(record.acreage, "acreage", warn, {
    64	        min: 0,
    65	        exclusiveMin: true,
    66	      }),
    67	      rating: numberInRange(record.rating, "rating", warn, { min: 0, max: 5 }),
    68	    });
    69	  });
    70	
    71	  parks.sort((a, b) => a.name.localeCompare(b.name, "en"));
    72	  return { parks, warnings };
    73	}
    74	
    75	/** Ids become URL path segments, so keep them to a URL-safe slug. */
    76	const ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]*$/;
    77	
    78	type Warn = (message: string) => void;
    79	
    80	function isObject(value: unknown): value is Record<string, unknown> {
    81	  return typeof value === "object" && value !== null && !Array.isArray(value);
    82	}
    83	
    84	/** A non-empty, trimmed string, or `null`. */
    85	function text(value: unknown): string | null {
    86	  if (typeof value !== "string") return null;
    87	  const trimmed = value.trim();
    88	  return trimmed === "" ? null : trimmed;
    89	}
    90	
    91	function numberInRange(
    92	  value: unknown,
    93	  field: string,
    94	  warn: Warn,
    95	  range: { min?: number; max?: number; exclusiveMin?: boolean },
    96	): number | null {
    97	  if (value === null || value === undefined) return null;
    98	  const valid =
    99	    typeof value === "number" &&
   100	    Number.isFinite(value) &&
   101	    (range.min === undefined ||
   102	      (range.exclusiveMin ? value > range.min : value >= range.min)) &&
   103	    (range.max === undefined || value <= range.max);
   104	  if (!valid) {
   105	    warn(`ignored invalid ${field} ${JSON.stringify(value)}.`);
   106	    return null;
   107	  }
   108	  return value;
   109	}
   110	
   111	function coordinates(
   112	  lat: unknown,
   113	  lng: unknown,
   114	  warn: Warn,
   115	): Coordinates | null {
   116	  if (lat == null && lng == null) return null;
   117	  const valid =
   118	    typeof lat === "number" &&
   119	    typeof lng === "number" &&
   120	    Number.isFinite(lat) &&
   121	    Number.isFinite(lng) &&
   122	    Math.abs(lat) <= 90 &&
   123	    Math.abs(lng) <= 180 &&
   124	    // (0, 0) is a common "unknown" placeholder, never a real park here.
   125	    !(lat === 0 && lng === 0);
   126	  if (!valid) {
   127	    warn(
   128	      `ignored invalid coordinates ${JSON.stringify({ lat, lng })}; the park will not appear on the map.`,
   129	    );
   130	    return null;
   131	  }
   132	  return { lat, lng };
   133	}
   134	
   135	function stringList(value: unknown, field: string, warn: Warn): string[] {
   136	  if (value === null || value === undefined) return [];
   137	  if (!Array.isArray(value)) {
   138	    warn(`ignored ${field} because it is not a list.`);
   139	    return [];
   140	  }
   141	  const items = value.map(text).filter((item) => item !== null);
   142	  if (items.length !== value.length) {
   143	    warn(`ignored ${value.length - items.length} empty or invalid ${field}.`);
   144	  }
   145	  return [...new Set(items)];
   146	}
   147	
   148	function imageUrls(value: unknown, warn: Warn): string[] {
   149	  return stringList(value, "images", warn).filter((url) => {
   150	    let protocol: string;
   151	    try {
   152	      protocol = new URL(url).protocol;
   153	    } catch {
   154	      protocol = "";
   155	    }
   156	    if (protocol === "https:" || protocol === "http:") return true;
   157	    warn(
   158	      `ignored image ${JSON.stringify(url)} because it is not an http(s) URL.`,
   159	    );
   160	    return false;
   161	  });
   162	}
