     1	/** Human-readable labels for amenity slugs that don't read well title-cased. */
     2	const AMENITY_LABELS: Record<string, string> = {
     3	  wifi: "Wi-Fi",
     4	  "dog-run": "Dog run",
     5	  "bike-path": "Bike path",
     6	  "splash-pad": "Splash pad",
     7	  "skate-park": "Skate park",
     8	  "kayak-launch": "Kayak launch",
     9	  "event-lawn": "Event lawn",
    10	  "gift-shop": "Gift shop",
    11	  "food-vendors": "Food vendors",
    12	  "picnic-areas": "Picnic areas",
    13	  "sports-fields": "Sports fields",
    14	  "water-fountain": "Water fountain",
    15	  "wildlife-viewing": "Wildlife viewing",
    16	  "accessible-paths": "Accessible paths",
    17	};
    18	
    19	/** `"dog-run"` → `"Dog run"`; unknown slugs fall back to sentence case. */
    20	export function amenityLabel(slug: string): string {
    21	  const known = AMENITY_LABELS[slug];
    22	  if (known) return known;
    23	  const words = slug.replace(/[-_]+/g, " ").trim();
    24	  return words.charAt(0).toUpperCase() + words.slice(1);
    25	}
    26	
    27	export function formatAcreage(acres: number): string {
    28	  const value = acres.toLocaleString("en-US", { maximumFractionDigits: 1 });
    29	  return `${value} ${acres === 1 ? "acre" : "acres"}`;
    30	}
    31	
    32	export function formatRating(rating: number): string {
    33	  return `${rating.toFixed(1)} out of 5`;
    34	}
    35	
    36	/**
    37	 * A link that opens turn-by-turn directions in Google Maps, which needs no
    38	 * API key. Coordinates are used rather than the address because several
    39	 * addresses in the data are incomplete (e.g. just a street name).
    40	 */
    41	export function directionsUrl(lat: number, lng: number): string {
    42	  const params = new URLSearchParams({
    43	    api: "1",
    44	    destination: `${lat},${lng}`,
    45	  });
    46	  return `https://www.google.com/maps/dir/?${params}`;
    47	}
=== src/lib/parks/search.ts
     1	import { amenityLabel } from "./format";
     2	import type { Park } from "./types";
     3	
     4	/**
     5	 * Case- and accent-insensitive search over the fields a resident is likely
     6	 * to type: name, address and amenities (by label, e.g. "dog run", or slug,
     7	 * e.g. "dog-run"). Every word in the query must match somewhere, so
     8	 * "brooklyn playground" narrows rather than widens the results.
     9	 *
    10	 * Descriptions are deliberately not searched: they mention things a park
    11	 * doesn't offer (e.g. "after they completed Central Park"), which would
    12	 * make results feel wrong.
    13	 */
    14	export function searchParks(parks: Park[], query: string): Park[] {
    15	  const words = normalize(query).split(" ").filter(Boolean);
    16	  if (words.length === 0) return parks;
    17	
    18	  return parks.filter((park) => {
    19	    const haystack = normalize(
    20	      [
    21	        park.name,
    22	        park.address ?? "",
    23	        ...park.amenities,
    24	        ...park.amenities.map(amenityLabel),
    25	      ].join(" "),
    26	    );
    27	    return words.every((word) => haystack.includes(word));
    28	  });
    29	}
    30	
    31	function normalize(text: string): string {
    32	  return text
    33	    .normalize("NFD")
    34	    .replace(/\p{Diacritic}/gu, "")
    35	    .toLowerCase()
    36	    .replace(/[^\p{Letter}\p{Number}]+/gu, " ")
    37	    .trim();
    38	}
