350	 */
351	function InvalidateSizeOnResize() {
352	  const map = useMap();
353	
354	  useEffect(() => {
355	    const observer = new ResizeObserver(() => map.invalidateSize());
356	    observer.observe(map.getContainer());
357	    return () => observer.disconnect();
358	  }, [map]);
359	
360	  return null;
361	}
362	
363	function usePrefersReducedMotion() {
364	  const [reduced] = useState(
365	    () =>
366	      typeof window !== "undefined" &&
367	      window.matchMedia("(prefers-reduced-motion: reduce)").matches,
368	  );
369	  return reduced;
370	}
