     3	import { useEffect, useRef, useState, type ReactNode } from "react";
     4	
     5	/**
     6	 * Renders `children` only once this wrapper has a real size, then keeps them.
     7	 *
     8	 * Leaflet can't lay out a map inside a `display: none` container, and on
     9	 * phones the map starts hidden behind the List/Map toggle. Waiting also
    10	 * means phone users who never open the map never download it.
    11	 */
    12	export function RenderWhenVisible({ children }: { children: ReactNode }) {
    13	  const ref = useRef<HTMLDivElement>(null);
    14	  const [visible, setVisible] = useState(false);
    15	
    16	  useEffect(() => {
    17	    const element = ref.current;
    18	    if (!element || visible) return;
    19	    const observer = new ResizeObserver(() => {
    20	      if (element.clientWidth > 0 && element.clientHeight > 0) {
    21	        setVisible(true);
    22	      }
    23	    });
    24	    observer.observe(element);
    25	    return () => observer.disconnect();
    26	  }, [visible]);
    27	
    28	  return (
    29	    <div ref={ref} className="h-full w-full">
    30	      {visible && children}
    31	    </div>
    32	  );
    33	}
